-- Run in Supabase SQL Editor. Pilot system: teacher accounts via Supabase Auth.
create extension if not exists pgcrypto;
create table if not exists public.exam_rooms(id uuid primary key default gen_random_uuid(),teacher_id uuid not null references auth.users(id),code text not null unique,name text not null,subject text not null check(subject in ('Toán','Tin học','Công nghệ')),grade text not null,class_name text not null,duration int not null check(duration between 5 and 240),max_students int not null check(max_students between 1 and 500),mode text not null default 'Tập trung',approval boolean not null default true,status text not null default 'waiting' check(status in ('waiting','active','ended')),starts_at timestamptz,ends_at timestamptz,started_at timestamptz,created_at timestamptz default now());
create table if not exists public.room_participants(id uuid primary key default gen_random_uuid(),room_id uuid not null references public.exam_rooms(id) on delete cascade,name text not null,student_code text not null,class_name text not null,token_hash text not null,status text not null default 'pending' check(status in ('pending','approved','rejected','submitted')),joined_at timestamptz default now(),submitted_at timestamptz,score numeric(5,2),unique(room_id,student_code));
create table if not exists public.exam_questions(id uuid primary key default gen_random_uuid(),room_id uuid not null references public.exam_rooms(id) on delete cascade,position int not null,kind text not null check(kind in ('mcq','tf','short')),prompt text not null,options jsonb not null default '[]',answer text not null,unique(room_id,position));
create table if not exists public.student_answers(participant_id uuid not null references public.room_participants(id) on delete cascade,question_id uuid not null references public.exam_questions(id) on delete cascade,answer text not null,updated_at timestamptz default now(),primary key(participant_id,question_id));
create index if not exists participants_room_idx on public.room_participants(room_id);
create index if not exists questions_room_idx on public.exam_questions(room_id);
alter table public.exam_rooms enable row level security;alter table public.room_participants enable row level security;alter table public.exam_questions enable row level security;alter table public.student_answers enable row level security;
create policy "teacher rooms select" on public.exam_rooms for select to authenticated using(teacher_id=auth.uid());
create policy "teacher rooms insert" on public.exam_rooms for insert to authenticated with check(teacher_id=auth.uid());
create policy "teacher rooms update" on public.exam_rooms for update to authenticated using(teacher_id=auth.uid()) with check(teacher_id=auth.uid());
create policy "teacher participants read" on public.room_participants for select to authenticated using(exists(select 1 from public.exam_rooms r where r.id=room_id and r.teacher_id=auth.uid()));
create policy "teacher participants update" on public.room_participants for update to authenticated using(exists(select 1 from public.exam_rooms r where r.id=room_id and r.teacher_id=auth.uid()));
create policy "teacher questions" on public.exam_questions for all to authenticated using(exists(select 1 from public.exam_rooms r where r.id=room_id and r.teacher_id=auth.uid())) with check(exists(select 1 from public.exam_rooms r where r.id=room_id and r.teacher_id=auth.uid()));
-- Student data is accessed ONLY through tightly scoped security-definer RPCs.
create or replace function public.valid_student(p_token text) returns uuid language sql security definer set search_path=public as $$select id from public.room_participants where token_hash=encode(digest(p_token,'sha256'),'hex') limit 1$$;
revoke all on function public.valid_student(text) from public,anon,authenticated;
create or replace function public.join_exam_room(p_code text,p_name text,p_student_code text,p_class_name text) returns jsonb language plpgsql security definer set search_path=public as $$declare r public.exam_rooms; p public.room_participants; t text;begin
if length(trim(p_name))<2 or length(trim(p_student_code))<2 or length(trim(p_class_name))<1 then raise exception 'Thông tin học sinh không hợp lệ';end if;
select * into r from public.exam_rooms where code=upper(trim(p_code)) for update;
if not found or r.status='ended' then raise exception 'Phòng thi không tồn tại hoặc đã kết thúc';end if;
if r.status='active' and r.mode='Tập trung' then raise exception 'Phòng đã bắt đầu, không cho phép vào muộn';end if;
if (select count(*) from public.room_participants where room_id=r.id)>=r.max_students then raise exception 'Phòng đã đủ học sinh';end if;
if exists(select 1 from public.room_participants where room_id=r.id and student_code=trim(p_student_code)) then raise exception 'Mã học sinh đã tham gia phòng';end if;
t:=encode(gen_random_bytes(32),'hex');insert into public.room_participants(room_id,name,student_code,class_name,token_hash,status) values(r.id,left(trim(p_name),120),left(trim(p_student_code),40),left(trim(p_class_name),40),encode(digest(t,'sha256'),'hex'),case when r.approval then 'pending' else 'approved' end) returning * into p;
return jsonb_build_object('token',t,'name',p.name,'student_code',p.student_code,'status',p.status,'room_status',r.status);end$$;
create or replace function public.get_my_exam_state(p_token text) returns jsonb language plpgsql security definer set search_path=public as $$declare p public.room_participants;r public.exam_rooms;begin select * into p from public.room_participants where id=public.valid_student(p_token);if not found then raise exception 'Phiên tham gia không hợp lệ';end if;select * into r from public.exam_rooms where id=p.room_id;return jsonb_build_object('name',p.name,'student_code',p.student_code,'status',p.status,'score',p.score,'room_status',r.status);end$$;
create or replace function public.get_exam_questions(p_token text) returns jsonb language plpgsql security definer set search_path=public as $$declare p public.room_participants;r public.exam_rooms;deadline timestamptz;begin select * into p from public.room_participants where id=public.valid_student(p_token);if not found or p.status<>'approved' then raise exception 'Học sinh chưa được duyệt hoặc đã nộp bài';end if;select * into r from public.exam_rooms where id=p.room_id;if r.status<>'active' then raise exception 'Phòng chưa bắt đầu';end if;deadline:=r.started_at+make_interval(mins=>r.duration);if now()>=deadline then raise exception 'Đã hết thời gian làm bài';end if;
return jsonb_build_object('subject',r.subject,'grade',r.grade,'deadline',deadline,'questions',coalesce((select jsonb_agg(jsonb_build_object('id',q.id,'prompt',q.prompt,'kind',q.kind,'options',q.options) order by q.position) from public.exam_questions q where q.room_id=r.id),'[]'::jsonb),'saved_answers',coalesce((select jsonb_object_agg(a.question_id,a.answer) from public.student_answers a where a.participant_id=p.id),'{}'::jsonb));end$$;
create or replace function public.save_exam_answer(p_token text,p_question_id uuid,p_answer text) returns boolean language plpgsql security definer set search_path=public as $$declare p public.room_participants;r public.exam_rooms;begin select * into p from public.room_participants where id=public.valid_student(p_token);if not found or p.status<>'approved' then raise exception 'Không có quyền lưu đáp án';end if;select * into r from public.exam_rooms where id=p.room_id;if r.status<>'active' or now()>=r.started_at+make_interval(mins=>r.duration) then raise exception 'Bài thi đã hết hạn';end if;if not exists(select 1 from public.exam_questions where id=p_question_id and room_id=r.id) then raise exception 'Câu hỏi không thuộc phòng thi';end if;insert into public.student_answers(participant_id,question_id,answer) values(p.id,p_question_id,left(p_answer,2000)) on conflict(participant_id,question_id) do update set answer=excluded.answer,updated_at=now();return true;end$$;
create or replace function public.submit_exam(p_token text) returns jsonb language plpgsql security definer set search_path=public as $$declare p public.room_participants;r public.exam_rooms;points numeric:=0;v record;correct_count int;i int;begin select * into p from public.room_participants where id=public.valid_student(p_token) for update;if not found then raise exception 'Phiên thi không hợp lệ';end if;if p.status='submitted' then return jsonb_build_object('score',p.score);end if;if p.status<>'approved' then raise exception 'Chưa được phép thi';end if;select * into r from public.exam_rooms where id=p.room_id;if r.status not in ('active','ended') then raise exception 'Phòng chưa bắt đầu';end if;
for v in select q.kind,q.answer,a.answer as student_answer from public.exam_questions q left join public.student_answers a on a.question_id=q.id and a.participant_id=p.id where q.room_id=r.id loop
if v.kind='mcq' and v.student_answer=v.answer then points:=points+0.25;
elsif v.kind='short' and lower(trim(replace(coalesce(v.student_answer,''),',','.')))=lower(trim(replace(v.answer,',','.'))) then points:=points+0.5;
elsif v.kind='tf' then correct_count:=0;for i in 1..4 loop if substring(coalesce(v.student_answer,'____') from i for 1)=substring(v.answer from i for 1) then correct_count:=correct_count+1;end if;end loop;points:=points+case correct_count when 4 then 1 when 3 then 0.5 when 2 then 0.25 when 1 then 0.1 else 0 end;
end if;end loop;
update public.room_participants set status='submitted',score=points,submitted_at=now() where id=p.id;return jsonb_build_object('score',points);end$$;
grant execute on function public.join_exam_room(text,text,text,text),public.get_my_exam_state(text),public.get_exam_questions(text),public.save_exam_answer(text,uuid,text),public.submit_exam(text) to anon,authenticated;
-- Generate a sample 22-question exam for each newly created room. Replace with approved question bank for production.
create or replace function public.seed_room_questions() returns trigger language plpgsql security definer set search_path=public as $$declare i int;stem text;begin
for i in 1..12 loop
stem:=case new.subject when 'Toán' then 'Tính '||i||' + '||(i+2)||' bằng bao nhiêu?' when 'Tin học' then 'Giá trị của biểu thức Python '||i||' + '||(i+2)||' là bao nhiêu?' else 'Một thiết bị có '||i||' bộ phận và bổ sung '||(i+2)||' bộ phận. Tổng số là bao nhiêu?' end;
insert into public.exam_questions(room_id,position,kind,prompt,options,answer) values(new.id,i,'mcq',stem,jsonb_build_array((i*2+1)::text,(i*2+2)::text,(i*2+3)::text,(i*2+4)::text),'1');end loop;
for i in 13..16 loop insert into public.exam_questions(room_id,position,kind,prompt,options,answer) values(new.id,i,'tf','Xác định đúng/sai các mệnh đề sau:',jsonb_build_array('2 + 2 = 4','3 > 5','10 chia hết cho 2','7 là số chẵn'),'TFTF');end loop;
for i in 17..22 loop insert into public.exam_questions(room_id,position,kind,prompt,options,answer) values(new.id,i,'short','Tính '||i||' + 3.', '[]'::jsonb,(i+3)::text);end loop;
return new;end$$;
drop trigger if exists seed_exam_questions on public.exam_rooms;create trigger seed_exam_questions after insert on public.exam_rooms for each row execute function public.seed_room_questions();
-- Realtime updates for teacher dashboard; enable in Supabase Dashboard if not already published.
do $$begin alter publication supabase_realtime add table public.room_participants;exception when duplicate_object then null;end$$;
do $$begin alter publication supabase_realtime add table public.exam_rooms;exception when duplicate_object then null;end$$;
